body:
**Unified patch — CODER 9 phase 1 (C9-1/C9-2/C9-3 + law tests), source-only.**
Apply to base `25b5a01b2313d681d2dd24d1d4c108110f13395a` (`git apply coder9_phase1.patch`), then build `make -j$(nproc) all` inside `miniandroid/`.
Changed source files: `apk_parser.{h,cpp}`, `bitmap_shadow.{h,cpp}`, `dalvik_engine.cpp` (5 files) + 2 new law tests. The synthetic harness (fixture + validator script) ships in the same working tree; ask if you want it as a second patch.

```diff
diff --git a/miniandroid/src/apk/apk_parser.cpp b/miniandroid/src/apk/apk_parser.cpp
index d740269d..ea4b8f68 100755
--- a/miniandroid/src/apk/apk_parser.cpp
+++ b/miniandroid/src/apk/apk_parser.cpp
@@ -392,6 +392,41 @@ bool ApkParser::parse_central_directory(const std::vector<uint8_t>& data, size_t

         entry.is_directory = !entry.name.empty() && entry.name.back() == '/';

+        // ── C9-2 (CODER 9) — resolve the entry DATA offset from the LOCAL
+        // file header. The central directory records the LFH offset; the
+        // AssetFileDescriptor contract (AssetManager.openFd) needs the
+        // offset of the DATA that follows it. LFH name/extra lengths are
+        // read from the LFH ITSELF — APPNOTE.TXT §4.4.11 allows LFH extra
+        // fields to differ from CDE extra fields, so the CDE-derived
+        // arithmetic would be wrong for such archives. A mismatching or
+        // out-of-bounds LFH leaves has_data_offset=false (honest miss);
+        // extraction (extract_entry_using_central_dir_) revalidates
+        // independently, so this never weakens the existing byte laws.
+        do {
+            const size_t lfh_off = entry.offset;
+            if (lfh_off + sizeof(ZipLocalFileHeader) > data.size()) break;
+            if (lfh_off + sizeof(ZipLocalFileHeader) < lfh_off) break;  // overflow guard
+            ZipLocalFileHeader lfh;
+            std::memcpy(&lfh, &data[lfh_off], sizeof(lfh));
+            if (lfh.signature != ZIP_LOCAL_FILE_HEADER_SIG) {
+                log("C9-2: LFH signature mismatch for entry '" + entry.name +
+                    "' at offset " + std::to_string(lfh_off) +
+                    " — data_offset unresolved");
+                break;
+            }
+            const uint64_t data_off = (uint64_t)lfh_off + sizeof(ZipLocalFileHeader) +
+                                      lfh.file_name_length + lfh.extra_field_length;
+            if (data_off > data.size() ||
+                data_off + entry.compressed_size > data.size()) {
+                log("C9-2: data offset " + std::to_string(data_off) +
+                    " out of bounds for entry '" + entry.name +
+                    "' — data_offset unresolved");
+                break;
+            }
+            entry.data_offset = data_off;
+            entry.has_data_offset = true;
+        } while (false);
+        
         entries.push_back(entry);

         // Move to next entry
diff --git a/miniandroid/src/apk/apk_parser.h b/miniandroid/src/apk/apk_parser.h
index 938aedae..f6bfd596 100755
--- a/miniandroid/src/apk/apk_parser.h
+++ b/miniandroid/src/apk/apk_parser.h
@@ -158,6 +158,17 @@ struct ZipEntry {
     uint32_t crc32 = 0;
     uint32_t offset = 0;  // Offset to local file header
     bool is_directory = false;
+    // ── C9-2 (CODER 9) — AssetFileDescriptor data-offset law ────────────
+    // AOSP AssetManager.openFd (AssetManager2.java → Asset, APPNOTE.TXT
+    // §4.3.7): an uncompressed entry is addressable at the offset of its
+    // DATA, not of its local file header. data_offset = LFH offset + 30 +
+    // LFH file_name_length + LFH extra_field_length — resolved from the
+    // LOCAL header because LFH and CDE extra fields may legally differ
+    // (APPNOTE.TXT §4.4.11). has_data_offset=false means the LFH could not
+    // be validated (hostile/truncated archive) and consumers must not
+    // pretend the offset is the data (honest-miss law).
+    uint64_t data_offset = 0;
+    bool has_data_offset = false;
 };

 // Callback for progress reporting
