+// the longjmp.
+static bool c9_png_encode_rgba(int w, int h,
+                               const std::vector<uint8_t>& rgba,
+                               std::vector<uint8_t>* out) {
+    if (w <= 0 || h <= 0 || rgba.size() != (size_t)w * h * 4 || !out)
+        return false;
